function CalcBaseFee(parent Header, timestamp uint64) *big.Int {
  // If London not active, no base fee
  if !config.IsLondon(parent.Number+1) {
    return nil
  }

  parentGasTarget := parent.GasLimit / ElasticityMultiplier  // ElasticityMultiplier = 2
  parentGasUsed := parent.GasUsed

  // If parent gas equals target, base fee unchanged
  if parentGasUsed == parentGasTarget {
    return new(big.Int).Set(parent.BaseFee)
  }

  var baseFee *big.Int
  if parentGasUsed > parentGasTarget {
    // Gas usage above target: increase base fee
    gasUsedDelta := parentGasUsed - parentGasTarget
    baseFeeDelta := parent.BaseFee * gasUsedDelta / parentGasTarget / BaseFeeChangeDenominator  // Denominator = 8
    baseFee = parent.BaseFee + max(1, baseFeeDelta)  // Minimum increase 1 wei
  } else {
    // Gas usage below target: decrease base fee
    gasUsedDelta := parentGasTarget - parentGasUsed
    baseFeeDelta := parent.BaseFee * gasUsedDelta / parentGasTarget / BaseFeeChangeDenominator
    baseFee = parent.BaseFee - baseFeeDelta
    if baseFee < 0 { baseFee = 0 }  // Floor at 0
  }
  return baseFee
}
