function CalcBlobFee(excessBlobGas uint64, blobConfig *BlobConfig) *big.Int {
  // Exponential formula: e^(excessBlobGas / updateFraction)
  // Approximated as: baseFeePerBlobGas = minBlobGasPrice * e^(excessBlobGas / updateFraction)

  // Fast path: no excess blob gas means minimum price
  if excessBlobGas == 0 {
    return big.NewInt(params.BlobTxMinBlobGasprice)  // 1 wei
  }

  // Compute exponent: excessBlobGas / updateFraction
  // Use fixed-point math to avoid floating point
  fakeExponential := FakeExponential(
    minBlobGasPrice,
    excessBlobGas,
    blobConfig.UpdateFraction,
  )

  return fakeExponential
}

function FakeExponential(numerator, exponent, denominator) *big.Int {
  // Taylor series approximation of e^(exponent/denominator)
  // More accurate than true exponential, avoids overflow
  output := numerator * denominator
  accumulator := denominator

  for i := 1; accumulator > 0; i++ {
    accumulator = accumulator * exponent / (denominator * i)
    output += numerator * accumulator
  }

  return output / denominator
}

function CalcExcessBlobGas(parent Header, blobConfig *BlobConfig) uint64 {
  // Accumulate excess blob gas from parent
  parentExcess := parent.ExcessBlobGas
  parentBlobGasUsed := parent.BlobGasUsed
  targetBlobGas := blobConfig.Target * params.BlobTxBlobGasPerBlob  // 131,072 gas per blob

  // If parent used more blobs than target, accumulate excess
  // Otherwise, reduce excess (but floor at 0)
  excessBlobGas := parentExcess + parentBlobGasUsed
  if excessBlobGas < targetBlobGas {
    return 0
  }
  return excessBlobGas - targetBlobGas
}
