function IntrinsicGas(
  data []byte,
  accessList AccessList,
  authList []SetCodeAuthorization,
  isContractCreation bool,
  isHomestead bool,
  isEIP2028 bool,
  isEIP3860 bool,
) (uint64, error) {

  // Base transaction cost
  var gas uint64
  if isContractCreation && isHomestead {
    gas = 53000  // TxGasContractCreation
  } else {
    gas = 21000  // TxGas
  }

  // Data cost (calldata)
  if len(data) > 0 {
    zeroBytes := countBytes(data, 0x00)
    nonZeroBytes := len(data) - zeroBytes

    // Zero bytes: 4 gas each
    gas += zeroBytes * 4  // TxDataZeroGas

    // Non-zero bytes: 68 gas before EIP-2028, 16 gas after
    if isEIP2028 {
      gas += nonZeroBytes * 16  // TxDataNonZeroGasEIP2028
    } else {
      gas += nonZeroBytes * 68  // TxDataNonZeroGasFrontier
    }

    // Init code cost (EIP-3860): 2 gas per 32-byte word
    if isContractCreation && isEIP3860 {
      words := (len(data) + 31) / 32
      gas += words * 2  // InitCodeWordGas
    }
  }

  // Access list cost (EIP-2930)
  if accessList != nil {
    gas += len(accessList) * 2400  // TxAccessListAddressGas
    gas += accessList.StorageKeys() * 1900  // TxAccessListStorageKeyGas
  }

  // Authorization list cost (EIP-7702)
  if authList != nil {
    gas += len(authList) * 25000  // CallNewAccountGas per authorization
  }

  return gas, nil
}
