function EffectiveTipPerGas(tx *Transaction, baseFee *big.Int) *big.Int {
  if baseFee == nil {
    // Pre-London: use legacy gasPrice
    return tx.GasPrice
  }

  // EIP-1559 transaction
  // Effective tip is min of:
  // 1. maxPriorityFeePerGas (user's declared tip)
  // 2. maxFeePerGas - baseFee (remaining budget after base fee)

  if tx.GasFeeCap < baseFee {
    // Transaction cannot afford base fee (invalid for mempool)
    return big.NewInt(0)
  }

  remainingBudget := tx.GasFeeCap - baseFee
  return min(tx.GasTipCap, remainingBudget)
}

function EffectiveGasPrice(tx *Transaction, baseFee *big.Int) *big.Int {
  // Actual gas price charged (tip + base fee)
  return baseFee + EffectiveTipPerGas(tx, baseFee)
}

function TransactionOrdering(txs []*Transaction, baseFee *big.Int) []*Transaction {
  // Sort transactions by effective tip (descending)
  sort.Slice(txs, func(i, j int) bool {
    tipI := EffectiveTipPerGas(txs[i], baseFee)
    tipJ := EffectiveTipPerGas(txs[j], baseFee)

    if tipI == tipJ {
      // Tie-break by nonce for same sender
      if txs[i].From == txs[j].From {
        return txs[i].Nonce < txs[j].Nonce
      }
      // Tie-break by gas price for different senders
      return txs[i].GasPrice > txs[j].GasPrice
    }
    return tipI > tipJ
  })
  return txs
}
