function ExecuteEVM(msg Message, state StateDB, gasPool *GasPool) (*Receipt, error) {
  gasLimit := msg.GasLimit
  gasRemaining := gasLimit
  gasRefund := 0

  // Execute each opcode
  for pc := 0; pc < len(code); pc++ {
    op := code[pc]

    // Static gas cost (e.g., ADD = 3, MUL = 5, SLOAD = see dynamic)
    staticGas := gasTable[op]
    if gasRemaining < staticGas {
      return nil, ErrOutOfGas
    }
    gasRemaining -= staticGas

    // Dynamic gas cost (memory, storage, calls)
    dynamicGas := 0
    switch op {
      case SLOAD:
        // EIP-2929: cold = 2100, warm = 100
        if state.IsSlotCold(address, slot) {
          dynamicGas = 2100
          state.MarkSlotWarm(address, slot)
        } else {
          dynamicGas = 100
        }

      case SSTORE:
        // Complex gas based on current/original/new values
        // EIP-2200 net gas metering with EIP-3529 refund cap
        if original == current && current != new {
          if original == 0 {
            dynamicGas = 20000  // Store to empty slot
          } else {
            dynamicGas = 2900   // Modify existing slot (cold)
          }
        } else {
          dynamicGas = 100  // Warm storage
        }

        // Refunds (capped at gasUsed / 5 at end)
        if original != 0 && new == 0 {
          gasRefund += 4800  // Clear storage
        }

      case CALL, DELEGATECALL, STATICCALL:
        // Base call cost + value transfer + new account
        dynamicGas = 0
        if !state.IsAddressWarm(target) {
          dynamicGas += 2600  // Cold account access
          state.MarkAddressWarm(target)
        }
        if value > 0 {
          dynamicGas += 9000  // Value transfer
        }
        if !state.Exists(target) && value > 0 {
          dynamicGas += 25000  // New account creation
        }
        // Plus gas stipend for callee

      case MLOAD, MSTORE:
        // Memory expansion cost: quadratic
        memorySize := (offset + 32 + 31) / 32 * 32
        if memorySize > currentMemorySize {
          expansion := memorySize - currentMemorySize
          dynamicGas = (expansion * 3) + (expansion^2 / 512)
        }
    }

    if gasRemaining < dynamicGas {
      return nil, ErrOutOfGas
    }
    gasRemaining -= dynamicGas

    // Execute opcode logic
    ExecuteOpcode(op, state)
  }

  // Cap refund at gasUsed / 5 (EIP-3529)
  gasUsed := gasLimit - gasRemaining
  refundQuotient := 5
  if gasRefund > gasUsed / refundQuotient {
    gasRefund = gasUsed / refundQuotient
  }

  // Refund capped amount
  gasRemaining += gasRefund
  gasUsed = gasLimit - gasRemaining

  return &Receipt{GasUsed: gasUsed}, nil
}
