function ValidateBlock(block *Block, parent *Block, stateDB StateDB) error {
  // Phase 1: ValidateBody (structural checks, no state execution)

  // Verify parent relationship
  if block.ParentHash != parent.Hash() {
    return ErrInvalidParent
  }
  if block.Number != parent.Number + 1 {
    return ErrInvalidNumber
  }

  // Post-merge: uncles must be empty
  if isPostMerge && len(block.Uncles) > 0 {
    return ErrInvalidUncleHash
  }

  // Verify transaction root matches transactions
  txRoot := DeriveSha(block.Transactions)
  if block.TxHash != txRoot {
    return ErrInvalidTxRoot
  }

  // Verify uncle hash (must be EmptyUncleHash post-merge)
  uncleHash := CalcUncleHash(block.Uncles)
  if block.UncleHash != uncleHash {
    return ErrInvalidUncleHash
  }

  // Shanghai+: verify withdrawals root
  if block.Withdrawals != nil {
    withdrawalRoot := DeriveSha(block.Withdrawals)
    if block.WithdrawalsHash != withdrawalRoot {
      return ErrInvalidWithdrawalsRoot
    }
  }

  // Cancun+: verify blob gas usage
  if isCancun {
    blobGasUsed := 0
    for _, tx := range block.Transactions {
      if tx.Type == BlobTxType {
        blobGasUsed += len(tx.BlobHashes) * params.BlobTxBlobGasPerBlob
      }
    }
    if block.BlobGasUsed != blobGasUsed {
      return ErrInvalidBlobGasUsed
    }
  }

  // EIP-7934 (Osaka): verify block size under 8MB
  if isOsaka && block.Size() > params.MaxBlockSize {
    return ErrOversizedBlock
  }

  // Phase 2: Execute transactions (state transition)
  receipts, gasUsed, err := ProcessBlock(block, stateDB)
  if err != nil {
    return err
  }

  // Phase 3: ValidateState (verify execution results)

  // Verify gas used matches header
  if block.GasUsed != gasUsed {
    return ErrInvalidGasUsed
  }

  // Verify receipts root
  receiptRoot := DeriveSha(receipts)
  if block.ReceiptHash != receiptRoot {
    return ErrInvalidReceiptsRoot
  }

  // Verify logs bloom filter
  bloom := CreateBloom(receipts)
  if block.Bloom != bloom {
    return ErrInvalidBloom
  }

  // Verify state root (most critical check)
  stateRoot := stateDB.IntermediateRoot()
  if block.Root != stateRoot {
    return ErrInvalidStateRoot
  }

  // Prague+: verify requests hash (deposits, withdrawals, consolidations)
  if isPrague && block.Requests != nil {
    requestsHash := DeriveSha(block.Requests)
    if block.RequestsHash != requestsHash {
      return ErrInvalidRequestsHash
    }
  }

  return nil
}
