function ComputeStateRoot(stateDB *StateDB) common.Hash {
  // State organized as Merkle Patricia Trie (MPT)
  // Key: keccak256(address) for accounts
  // Value: RLP(nonce, balance, storageRoot, codeHash)

  trie := stateDB.trie

  // Update all modified accounts
  for address, stateObject := range stateDB.stateObjects {
    if stateObject.deleted {
      // Delete account from trie
      trie.Delete(keccak256(address))
      continue
    }

    if stateObject.dirty {
      // Compute storage root for account's storage trie
      storageRoot := ComputeStorageRoot(stateObject.storage)

      // Encode account state
      account := Account{
        Nonce:       stateObject.nonce,
        Balance:     stateObject.balance,
        StorageRoot: storageRoot,
        CodeHash:    keccak256(stateObject.code),
      }

      // Update account in state trie
      trie.Update(keccak256(address), RLPEncode(account))
    }
  }

  // Commit trie changes to database
  root, nodes := trie.Commit(collectNodes = true)

  // Write nodes to persistent storage
  trieDB.Update(root, nodes)

  return root
}

function ComputeStorageRoot(storage map[common.Hash]common.Hash) common.Hash {
  // Storage trie: key = keccak256(slot), value = RLPEncode(value)
  storageTrie := NewTrie()

  for slot, value := range storage {
    if value == 0 {
      // Zero values deleted from trie (storage refund optimization)
      storageTrie.Delete(keccak256(slot))
    } else {
      storageTrie.Update(keccak256(slot), RLPEncode(value))
    }
  }

  return storageTrie.Hash()
}
